import { IPlayerData } from '../models/player-data';
import { IPromoDetails } from '../models/promo-details';
import { RequestType } from '../models/request-type';
import { IResultCodeData } from '../models/result-code-data';
import { ISessionData } from '../models/session-data';
import { ISessionSettings } from '../models/session-settings';
import { ISessionStatus } from '../models/session-status';
import { ITimeKeeperLimit } from '../models/time-keeper-limit';

export interface IGameServerResponse {
    RequestType: RequestType;
    PlayerData: IPlayerData;
    ResultCode: IResultCodeData;
    ServiceDetails: { [index: string]: string };
    TimeKeeperLimit?: ITimeKeeperLimit;
    PromoDetails: IPromoDetails[];
    SessionData?: ISessionData;
    SessionStatus?: ISessionStatus;
    SessionSettings?: ISessionSettings;
}

export interface IUkGameServerResponse extends IGameServerResponse {
    SessionData: ISessionData | undefined;
    SessionStatus: undefined;
}

export interface IItGameServerResponse extends IGameServerResponse {
    SessionData: undefined;
    SessionStatus: ISessionStatus;
}
